package cminor.messages.errors.syntax;

import cminor.messages.errors.Error;
import cminor.messages.errors.scope.ScopeError;
import cminor.utilities.PrettyPrint;

/**
 * An {@link Error} generated by the {@link cminor.parser.Parser}.
 * @author Daniel Levy
 */
public class SyntaxError extends Error {

    protected String location;

    /** Indicates whether the {@link cminor.lexer.Lexer} or the {@link cminor.parser.Parser} generated the error. */
    protected boolean parser = true;

    /**
     * {@inheritDoc}
     */
    @Override
    protected String buildMessageHeader(String fileName) {
        return super.buildMessageHeader(fileName)
                + PrettyPrint.RED
                + "Syntax Error "
                + messageNumber()
                + ": ";
    }

    @Override
    public void createMessage(String fileName) {
        msg = buildMessageHeader(fileName) + buildMainMessage() + PrettyPrint.RESET + location;
        String sub = buildSupplementalMessage();
        msg += (sub.isEmpty()) ? "\n" : sub;
    }

    public boolean isLexerError() { return !parser; }

    public void setLexerMode() { parser = false; }

    /**
     * {@inheritDoc}
     */
    public boolean isSyntaxError() { return true; }

    /**
     * {@inheritDoc}
     */
    public SyntaxError asSyntaxError() { return this; }
}
